"""The slides.html page around the converted slides."""
import html
import json
import re

PAGE = """<!DOCTYPE html>
<!-- GENERATED by tools/tex2html from {src} -- edit the .tex files, then
     re-run the tool; changes made here are overwritten. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title}</title>
<link rel="stylesheet" href="html/deck.css">
<script>
window.DECK_CONFIG = {config};
</script>
</head>
<body>
<div class="deck">

{slides}

</div>
<script src="html/references.js"></script>
<script src="html/deck.js"></script>
<script type="text/x-mathjax-config">
  MathJax.Hub.Config({{
    tex2jax: {{ inlineMath: [["\\\\(", "\\\\)"]], displayMath: [["\\\\[", "\\\\]"], ["$$", "$$"]],
               processEscapes: true, processEnvironments: true }},
    CommonHTML: {{ scale: 100 }},
    showMathMenu: false, messageStyle: "none",
  }});
</script>
<script src="html/vendor/mathjax/MathJax.js?config=TeX-AMS_CHTML"></script>
</body>
</html>
"""


def render_page(src, config, slides):
    title = re.sub(r"<[^>]+>", " ", config.get("title", "Presentation"))
    return PAGE.format(src=src, title=html.escape(" ".join(title.split())),
                       config=json.dumps(config, indent=2, ensure_ascii=False),
                       slides="\n\n".join(slides))
